import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"术语表","description":"","frontmatter":{},"headers":[],"relativePath":"zh/glossary.md","filePath":"zh/glossary.md"}`),a={name:`zh/glossary.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to “术语表”">​</a></h1><p><a href="/faultdeck/glossary.html">English glossary</a>。这些术语按实现职责归纳,不按目录命名。各层落位见<a href="/faultdeck/zh/architecture.html#源码分层解说">架构</a>。</p><table tabindex="0"><thead><tr><th>术语</th><th>English</th><th>定义</th><th>file:line</th></tr></thead><tbody><tr><td>故障规格</td><td><code>FaultSpec</code></td><td>延迟、丢包或断连语义的标签模型,由用户入口、coordinator、agent 和适配器共享。</td><td><code>crates/core/src/lib.rs:26</code></td></tr><tr><td>故障目标</td><td><code>Target</code></td><td>可选的 IPv4 源地址、目标地址和目标端口选择器,用于限定一次注入。</td><td><code>crates/core/src/lib.rs:44</code></td></tr><tr><td>注入请求</td><td><code>Injection</code></td><td>一个故障加一个目标;这对数据是共享执行契约。</td><td><code>crates/core/src/lib.rs:82</code></td></tr><tr><td>内在校验</td><td>intrinsic validation</td><td>在后端行为执行前检查故障范围、非空目标和 IPv6 支持状态。</td><td><code>crates/core/src/lib.rs:108</code></td></tr><tr><td>管理网段保护</td><td>management-network protection</td><td>拒绝与操作者提供的受保护 CIDR 重叠的目标。</td><td><code>crates/core/src/lib.rs:142</code></td></tr><tr><td>执行器端口</td><td><code>CommandExecutor</code></td><td>netem 适配器执行或记录 <code>tc</code> 命令的边界;生产实现和测试实现都遵守它。</td><td><code>crates/netem/src/lib.rs:73</code></td></tr><tr><td>tc 命令</td><td><code>TcCommand</code></td><td>用程序加参数表示的一次可复现流量控制操作。</td><td><code>crates/netem/src/lib.rs:56</code></td></tr><tr><td>netem 适配器</td><td><code>NetemAdapter</code></td><td>在单网卡上规划、应用并回滚延迟与丢包的 qdisc/filter 状态。</td><td><code>crates/netem/src/lib.rs:172</code></td></tr><tr><td>pilot qdisc</td><td>pilot qdisc</td><td>FaultDeck 拥有的根 qdisc 句柄 <code>100:</code>,用于识别并只安全删除自己的流量控制状态。</td><td><code>crates/netem/src/lib.rs:13</code></td></tr><tr><td>断连路由</td><td>disconnect routing</td><td>Agent 把 disconnect 注入路由到 iptables,其余故障路由到 netem。</td><td><code>crates/agent/src/lib.rs:196</code></td></tr><tr><td>iptables 链</td><td>iptables chain</td><td><code>FAULTDECK</code> mangle 链及其 <code>INPUT</code> 跳转承载断连 DROP 规则。</td><td><code>crates/agent/src/firewall.rs:9</code></td></tr><tr><td>断连适配器</td><td>disconnect adapter</td><td><code>Iptables</code> 确保链存在、安装 DROP 规则,并执行幂等回滚。</td><td><code>crates/agent/src/firewall.rs:31</code></td></tr><tr><td>Agent 配置</td><td><code>AgentConfig</code></td><td>进程启动配置:监听地址、可选 token、目标网卡和管理网段。</td><td><code>crates/agent/src/lib.rs:90</code></td></tr><tr><td>单活动故障</td><td>single active fault</td><td>Agent 宿主状态;回滚清除适配器标记前拒绝第二次注入。</td><td><code>crates/agent/src/lib.rs:191</code></td></tr><tr><td>Agent 线请求</td><td>agent wire request</td><td>Agent 宿主解码的 <code>ping</code>、<code>inject</code> 或 <code>rollback</code> 标签载荷。</td><td><code>crates/agent/src/lib.rs:109</code></td></tr><tr><td>Agent 线响应</td><td>agent wire response</td><td>返回给 CLI 的 <code>ok</code> 或 <code>error</code> 标签结果。</td><td><code>crates/agent/src/lib.rs:117</code></td></tr><tr><td>令牌鉴权</td><td>token authentication</td><td>每个进程边界的可选共享密钥比较;未设置 token 表示关闭鉴权。</td><td><code>crates/agent/src/lib.rs:124</code></td></tr><tr><td>NDJSON 帧</td><td>NDJSON frame</td><td>以换行分界的 JSON 值,硬性上限 64 KiB。</td><td><code>crates/agent/src/transport.rs:56</code></td></tr><tr><td>Mode A</td><td>Mode A</td><td>Agent 监听拓扑:控制器向常驻目标 Agent 打开一条 TCP 流。</td><td><code>crates/agent/src/transport.rs:94</code></td></tr><tr><td>Mode B</td><td>Mode B</td><td>控制器监听的反向连接拓扑,通过重试和退避穿越 NAT。</td><td><code>crates/agent/src/transport.rs:118</code></td></tr><tr><td>中枢信封</td><td><code>WireMessage</code></td><td>coordinator 信封,携带可选 token 和一条控制命令。</td><td><code>crates/coordinator/src/lib.rs:235</code></td></tr><tr><td>中枢命令</td><td><code>AgentCommand</code></td><td>coordinator 接受的注册、心跳、注入、回滚、取报告或列 Agent 操作。</td><td><code>crates/coordinator/src/lib.rs:69</code></td></tr><tr><td>中枢响应</td><td><code>AgentResponse</code></td><td>coordinator 的确认、入队回执、注册表列表、报告或错误结果。</td><td><code>crates/coordinator/src/lib.rs:80</code></td></tr><tr><td>Agent 身份</td><td><code>AgentIdentity</code></td><td>coordinator 保存的 Agent ID、能力列表、最近心跳时间和列表时计算的在线标志。</td><td><code>crates/coordinator/src/lib.rs:51</code></td></tr><tr><td>心跳</td><td>heartbeat</td><td>更新某个已注册 Agent 的 <code>last_seen_ms</code>;新鲜度参与在线判定。</td><td><code>crates/coordinator/src/lib.rs:178</code></td></tr><tr><td>Agent 链路</td><td>agent link</td><td>agent 到 coordinator 的出站连接;<code>LinkMessage::Dispatch</code> 沿其下行,<code>Result</code>/<code>Heartbeat</code> 沿其上行。</td><td><code>crates/coordinator/src/lib.rs:134</code></td></tr><tr><td>在线状态</td><td>online status</td><td>链路存活或心跳在 <code>HEARTBEAT_TIMEOUT_MS</code>(30 s)内;离线 agent 从 <code>available</code> 剔除。</td><td><code>crates/coordinator/src/lib.rs:211</code></td></tr><tr><td>指令入队</td><td>queued command</td><td>目标 agent 离线时,inject/rollback 持久保存在其队列中,下次注册时补发。</td><td><code>crates/coordinator/src/lib.rs:351</code></td></tr><tr><td>场景</td><td><code>Scenario</code></td><td>带名称的注入;其稳定序列化是哈希和报告的输入。</td><td><code>crates/report/src/lib.rs:38</code></td></tr><tr><td>场景哈希</td><td>scenario hash</td><td>场景的 SHA-256 身份,用于报告查找和比较。</td><td><code>crates/report/src/lib.rs:49</code></td></tr><tr><td>运行报告</td><td><code>RunReport</code></td><td>权威结果模型,包含场景身份、时间戳、证据和回放文本。</td><td><code>crates/report/src/lib.rs:78</code></td></tr><tr><td>回放命令</td><td>replay command</td><td>用户入口生成、保存进报告的 shell 引号安全 CLI 命令。</td><td><code>crates/cli/src/main.rs:315</code></td></tr><tr><td>恢复证据</td><td>restore evidence</td><td>回滚后的带时间戳检查,包含通过/失败和详情字段。</td><td><code>crates/report/src/lib.rs:63</code></td></tr><tr><td>外部断言</td><td>external assertion</td><td>附加到运行报告的具名外部观察结果。</td><td><code>crates/report/src/lib.rs:71</code></td></tr><tr><td>历史 diff</td><td>historical diff</td><td>对两份报告的事件、证据和断言集合做结构比较。</td><td><code>crates/report/src/lib.rs:175</code></td></tr></tbody></table>`,3)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};